interface ProductsUpdateEvent extends CustomEvent {
  detail: {
    sections: {
      [key: string]: string;
    };
  };
}

class FilterForm extends HTMLElement {
  private unsubscribe: (() => void) | undefined;
  private sectionId: string;
  private appliedFilters: NodeListOf<Element>;
  private clearAllHandler: ((e: MouseEvent) => Promise<void>) | undefined;

  constructor() {
    super();

    this.sectionId = this.getAttribute("data-section-id")!;
    this.appliedFilters = this.querySelectorAll('[js-filter="appied-filter"]')!;
  }

  async connectedCallback(): Promise<void> {
    if (!this.sectionId) {
      return;
    }

    this.unsubscribe = this.handleEvent<ProductsUpdateEvent>(
      "products:update",
      (event) => {
        const section = event.detail.sections[this.sectionId];

        if (!section) {
          return;
        }

        if (this.clearAllHandler) {
          this.removeEventListener("click", this.clearAllHandler);
        }

        const newFiltersForm = new DOMParser()
          .parseFromString(section, "text/html")
          .querySelector(this.tagName.toLowerCase())!;

        const filterLabels = this.querySelectorAll('[js-filter="label"]');
        const newFilterLabels = newFiltersForm.querySelectorAll(
          '[js-filter="label"]',
        );

        const filterInputs = this.querySelectorAll('[js-filter="input"]');
        const newFilterInputs = newFiltersForm.querySelectorAll(
          '[js-filter="input"]',
        );

        filterLabels.forEach((input, i) =>
          input.replaceWith(newFilterLabels[i]),
        );

        filterInputs.forEach((input, i) =>
          input.replaceWith(newFilterInputs[i]),
        );

        const appliedFilters = this.querySelector(
          '[js-filter="applied-filters"]',
        );

        const newAppliedFilters = newFiltersForm.querySelector(
          '[js-filter="applied-filters"]',
        );

        if (appliedFilters && newAppliedFilters) {
          appliedFilters.replaceWith(newAppliedFilters);
          this.appliedFilters = newAppliedFilters.querySelectorAll(
            '[js-filter="appied-filter"]',
          );

          this.handleAppliedFilters();
        }

        const submitBtn = this.querySelector('[js-filter="submit"]');
        const newSubmitBtn = newFiltersForm.querySelector(
          '[js-filter="submit"]',
        );

        if (submitBtn && newSubmitBtn) {
          submitBtn.replaceWith(newSubmitBtn);

          newSubmitBtn.addEventListener("click", () => {
            setTimeout(() => {
              const collection = document.querySelector(".collection");
              if (collection) {
                collection.setAttribute("data-filter-open", "false");
              }
            }, 300);
          });
        }

        this.setupClearAll();
      },
    );

    this.querySelector("form")?.addEventListener("input", async (e) => {
      const event = e.target as HTMLInputElement;

      if (!event.form) {
        return;
      }

      const searchParams = [
        event.form,
        document.querySelector("uwp-sort-form form"),
      ]
        .filter(Boolean)
        .map((f) => {
          if (
            event.type === "radio" &&
            f?.classList.contains("sort-form__form")
          ) {
            return;
          }

          // @ts-expect-error - TS doesn't know that filter(Boolean) removes nulls
          return new URLSearchParams(new FormData(f)).toString();
        })
        .filter(Boolean)
        .join("&");

      const sections = await fetch(
        `${location.pathname}?sections=${this.sectionId}&${searchParams}`,
      ).then((r) => r.json());

      document.dispatchEvent(
        new CustomEvent("products:update", {
          detail: { sections },
        }),
      );

      history.pushState(
        { searchParams },
        "",
        `${window.location.pathname}${
          searchParams.includes("?") || !searchParams
            ? searchParams
            : "?".concat(searchParams)
        }`,
      );
    });

    this.setupClearAll();
    this.handleAppliedFilters();
  }

  private setupClearAll(): void {
    this.clearAllHandler = async (e: MouseEvent) => {
      const button = (e.target as Element).closest('[js-filter="clear-all"]');

      if (!button) {
        return;
      }

      const params = new URLSearchParams(location.search);
      const query = params.get("q")!;
      const type = params.get("type")!;

      const sortForm =
        document.querySelector<HTMLFormElement>("uwp-sort-form form")!;

      const formParams = new FormData(sortForm);

      if (document.body.classList.contains("collection-template")) {
        formParams.append("q", query);
        formParams.append("type", type);
      }

      // @ts-expect-error - TS doesn't know that filter(Boolean) removes nulls
      const searchParams = new URLSearchParams(formParams).toString();

      const sections = await fetch(
        `${location.pathname}?sections=${this.sectionId}&${searchParams}`,
      ).then((r) => r.json());

      document.dispatchEvent(
        new CustomEvent("products:update", {
          detail: { sections },
        }),
      );

      history.pushState(
        { searchParams },
        "",
        `${window.location.pathname}${
          searchParams.includes("?") || !searchParams
            ? searchParams
            : "?".concat(searchParams)
        }`,
      );
    };

    this.addEventListener("click", this.clearAllHandler);
  }

  private handleAppliedFilters(): void {
    this.appliedFilters.forEach((filter) => {
      filter.addEventListener("click", async (event) => {
        const target = event.currentTarget as HTMLElement;
        const searchParams = target.getAttribute("data-url")!.split("?")[1];

        const sections = await fetch(
          `${location.pathname}?sections=${this.sectionId}&${searchParams}`,
        ).then((r) => r.json());

        document.dispatchEvent(
          new CustomEvent("products:update", {
            detail: { sections },
          }),
        );

        history.pushState(
          { searchParams },
          "",
          `${window.location.pathname}${
            searchParams.includes("?") || !searchParams
              ? searchParams
              : "?".concat(searchParams)
          }`,
        );
      });
    });
  }

  private handleEvent<T extends Event>(
    eventName: string,
    handler: (event: T) => void,
  ): () => void {
    const boundHandler = (event: Event) => handler(event as T);

    document.addEventListener(eventName, boundHandler);

    return () => document.removeEventListener(eventName, boundHandler);
  }

  disconnectedCallback(): void {
    if (this.unsubscribe) {
      this.unsubscribe();
    }
  }
}

customElements.define("uwp-filter-form", FilterForm);
